t = int(input())
for _ in range(t):
	(n, k) = map(int, input().split())
	l = input().split()
	if k == n and l[::-1] == l:
		print('YES')
	elif k == n and l[::-1] != l:
		print('NO')
	elif n % 2:
		print('YES')
	elif k % 2:
		print('YES')
	else:
		diff = 0
		for i in range(n // 2):
			d = int(l[i]) - int(l[n - 1 - i])
			if d > 0:
				diff += d
			else:
				diff -= d
		if diff % 2:
			print('NO')
		else:
			print('YES')
